messages.content:
仅补充文档所称的彩色与多光谱输入结构。代码使用显式的 `m×n×c` 三维数组，并对输入维度、标签矩阵尺寸、中心矩阵尺寸及中心元素类型进行断言；这些 expected 均由实现的维度规则和文档输出定义直接确定。以下代码可追加到测试文件末尾。静态审阅未运行测试。

```julia
@testset "imsegkmeans 三维彩色与多光谱输入" begin
    @testset "三维彩色图像 Float32" begin
        I = rand(Float32, 8, 7, 3)
        k = 3
        L, Centers = imsegkmeans(
            I,
            k;
            NumAttempts=1,
            MaxIterations=2,
            Threshold=Float32(0.01),
        )

        @test ndims(I) == 3
        @test size(I) == (8, 7, 3)
        @test size(L) == (8, 7)
        @test size(Centers) == (k, 3)
        @test eltype(Centers) == eltype(I)
    end

    @testset "三维多光谱图像 Float32" begin
        I = rand(Float32, 8, 7, 4)
        k = 3
        L, Centers = imsegkmeans(
            I,
            k;
            NumAttempts=1,
            MaxIterations=2,
            Threshold=Float32(0.01),
        )

        @test ndims(I) == 3
        @test size(I) == (8, 7, 4)
        @test size(L) == (8, 7)
        @test size(Centers) == (k, 4)
        @test eltype(Centers) == eltype(I)
    end
end
```
